alter table public.inspector_applications enable row level security;
alter table public.idempotency_audit_logs enable row level security;
alter table public.job_failures enable row level security;
alter table public.bid_logs enable row level security;
alter table public.sms_bidders enable row level security;
alter table public.dealer_health_scores enable row level security;
alter table public.dealer_analytics enable row level security;
alter table public.notification_audit enable row level security;
revoke all on table public.transactions, public.marketplace_health, public.conversion_funnels, public.escrow_anomalies, public.escrow_risk_scores, public.escrow_audits, public.auction_integrity_flags, public.auction_risk_profiles, public.contacts, public.ntsa_verification_requests, public.inspector_applications, public.idempotency_audit_logs, public.job_failures, public.bid_logs, public.sms_bidders, public.dealer_health_scores, public.dealer_analytics, public.notification_audit from anon, authenticated;
grant all on table public.transactions, public.marketplace_health, public.conversion_funnels, public.escrow_anomalies, public.escrow_risk_scores, public.escrow_audits, public.auction_integrity_flags, public.auction_risk_profiles, public.contacts, public.ntsa_verification_requests, public.inspector_applications, public.idempotency_audit_logs, public.job_failures, public.bid_logs, public.sms_bidders, public.dealer_health_scores, public.dealer_analytics, public.notification_audit to service_role;
